#!/usr/bin/env python3
import json, os
HERE = os.path.dirname(os.path.abspath(__file__))
def W(**kw):
    code = kw["code"]
    p = os.path.join(HERE, "subjects", code.replace(".", "").replace("*", "x").lower() + ".json")
    json.dump(kw, open(p, "w"), indent=1)
    print("wrote", p)

